{"function":"async () => {
  const props = el => { const c = getComputedStyle(el); return {outline: c.outlineStyle+' '+c.outlineWidth+' '+c.outlineColor, boxShadow: c.boxShadow, border: c.borderColor+' '+c.borderWidth, bg: c.backgroundColor}; };
  const out = {};
  for (const id of ['nome','cpf','servico','unidade','data-preferencial','descricao','declaracao','forma-video']) {
    const el = document.getElementById(id);
    const before = props(el);
    el.focus({focusVisible:true});
    await new Promise(r=>setTimeout(r,300));
    out[id] = {before, after: props(el), active: document.activeElement.id, fv: el.matches(':focus-visible'), cls: el.className};
    el.blur();
  }
  return out;
}"}

